# Product pictures from the price book (JPEG, base64) - shown on the equipment cards
PRODUCT_IMAGES = json.loads(r'''{"wall": "", "ceiling": "", "ducted": "", "lossnay": "", "bluescience": ""}''')

# Plain, unbranded pictures shown until a manufacturer is chosen (and for brands we have no photo of)
GENERIC_IMAGES = json.loads(r'''{"wall": "", "ceiling": "", "ducted": "", "copper": "", "insulation": "", "pump": "", "drainpipe": "", "cable": "", "hose": "", "bracket": "", "wifi": "", "trunking": "", "tray": "", "feet": "", "engineer": "", "electrician": "", "other": ""}''')

BRANDS = ["Midea", "Mitsubishi", "Mitsubishi HI", "Fujitsu", "Panasonic", "Samsung"]

def brand_of(name):
    """The make at the start of an equipment name (handles two-word makes like Mitsubishi HI)."""
    for b in sorted(BRANDS + ["Lossnay"], key=len, reverse=True):
        if name.lower().startswith(b.lower() + " "):
            return b
    return name.split(" ")[0]

def brand_slug(b):
    return re.sub(r"[^a-z0-9]+", "_", b.lower()).strip("_")
BRAND_STYLE = {"Midea": "#00A0E9", "Mitsubishi": "#E60012", "Mitsubishi HI": "#003A8F", "Fujitsu": "#E60012", "Panasonic": "#0041C0", "Samsung": "#1428A0", "Lossnay": "#E60012"}

_IMG_DIR = Path(__file__).parent / "product_images"

@st.cache_data(show_spinner=False)
def _read_b64(path, mtime):
    import base64
    return base64.b64encode(Path(path).read_bytes()).decode()

def _file_image(stem):
    """A picture dropped into the product_images folder, e.g. samsung_wall.jpg or logo_samsung.png.
    File-name capitals and jpg/jpeg/png/webp don't matter, and the real format is detected from the file itself. Returns base64 or ''."""
    try:
        want = stem.lower()
        for f in sorted(_IMG_DIR.iterdir()):
            if f.is_file() and f.stem.lower() == want and f.suffix.lower() in (".jpg", ".jpeg", ".png", ".webp"):
                return _read_b64(str(f), f.stat().st_mtime)
    except Exception:
        pass
    return ""

def logo_for(brand):
    return _file_image("logo_" + brand_slug(brand))

def image_for(item):
    """Picture for an equipment line: a photo from the product_images folder if there is one, else the built-in Midea photo, else the plain generic picture."""
    n = item["name"].lower()
    brand = brand_slug(brand_of(item["name"]))
    if item["kind"] == "lossnay":
        return _file_image("air_exchange") or _file_image("lossnay") or PRODUCT_IMAGES.get("lossnay")
    if item["kind"] in ("wall", "ceiling", "ducted"):
        own = _file_image(f"{brand}_{item['kind']}")
        if own:
            return own
        return PRODUCT_IMAGES.get(item["kind"]) if brand == "midea" else GENERIC_IMAGES.get(item["kind"])
    # extras, materials and labour: a photo from the product_images folder if there is one, else a plain holding drawing
    for key, words in (("engineer", ("engineer",)), ("electrician", ("electrician",)), ("copper", ("copper",)), ("insulation", ("insulation",)),
                       ("pump", ("pump",)), ("hose", ("hose",)), ("drainpipe", ("drain pipe",)), ("cable", ("cable",)), ("bracket", ("bracket",)),
                       ("wifi", ("wifi", "wi-fi")), ("trunking", ("trunking",)), ("tray", ("wall tray", "tray")), ("feet", ("feet", "stand"))):
        if any(w in n for w in words):
            return GENERIC_IMAGES.get(key) or GENERIC_IMAGES.get("other")
    return GENERIC_IMAGES.get("other")

