# Contact details printed on paperwork are fixed, whoever is logged in or sells (overrides any saved config)
FIXED_CONTACT = {"email": "andy@steadytemp.co.uk", "phone": "01743 832049", "web": "www.steadytemp.co.uk"}

# ───────────────────────────── config load ─────────────────────────────
CONFIG_FILE = "config.json"

def load_config():
    cfg = default_config()
    ver = 12                                  # nothing saved yet = already the newest catalogue
    try:
        if Path(CONFIG_FILE).exists():
            saved = json.loads(Path(CONFIG_FILE).read_text(encoding="utf-8"))
            ver = int(saved.get("catalogue_version", 1)) if "catalogue" in saved else 12
            for k, v in saved.items():
                if isinstance(v, dict) and isinstance(cfg.get(k), dict):
                    cfg[k].update(v)
                else:
                    cfg[k] = v
    except Exception:
        pass
    _sys = {"wall", "ceiling", "ducted", "lossnay"}
    _fresh = default_config()["catalogue"]
    if ver < 2:        # v2: manufacturer + kW sizes replace the old model-number system lines (extras/materials/labour edits are kept)
        _saved_other = [i for i in cfg.get("catalogue", []) if i.get("kind") not in _sys and "blue science" not in i.get("name", "").lower()]
        _other = _saved_other or [i for i in _fresh if i["kind"] not in _sys]
        cfg["catalogue"] = [i for i in _fresh if i["kind"] in _sys] + _other
    elif ver < 5:      # v3-v5: more makes / sizes - add any system lines that are missing, leave edited prices alone
        _have = {i["name"] for i in cfg["catalogue"]}
        cfg["catalogue"] = cfg["catalogue"] + [i for i in _fresh if i["kind"] in _sys and i["name"] not in _have]
    if ver < 4:        # v4: the "price to be confirmed" warnings have been checked - clear them once (admin can still tick them again)
        for _i in cfg["catalogue"]:
            _i["tbc"] = False
    if ver < 6:        # v6: Electricians Labour line (same price as the engineer) - add it if missing
        _have6 = {i["name"] for i in cfg["catalogue"]}
        cfg["catalogue"] = cfg["catalogue"] + [i for i in _fresh if i["name"] == "Electricians Labour - 1 day" and i["name"] not in _have6]
    if ver < 7:        # v7: 10 year term (provisional rates) and commission unit = £2,500 profit
        if not any(int(r.get("months", 0)) == 120 for r in cfg["lease_rates"]):
            cfg["lease_rates"] = cfg["lease_rates"] + [r for r in default_config()["lease_rates"] if int(r["months"]) == 120]
        if float(cfg["costs"].get("unit_size", 0)) == 4000.0:
            cfg["costs"]["unit_size"] = 2500.0
    if ver < 8:        # v8: engineer and electrician day lines are £500 (cost and RRP)
        for _i in cfg["catalogue"]:
            if _i.get("group") == "Labour" and ("engineer" in _i["name"].lower() or "electrician" in _i["name"].lower()):
                _i["cost"] = 500.0; _i["rrp"] = 500.0
    if ver < 9:        # v9: the prices that were entered as "cost" were really RRP - they become the cost, and the RRP is lifted by the same markup
        for _i in cfg["catalogue"]:
            try:
                _c, _r = float(_i["cost"]), float(_i["rrp"])
            except Exception:
                continue
            if _i.get("group") == "Labour" or _c <= 0 or _r <= 0:
                continue
            _i["cost"] = round(_r, 2); _i["rrp"] = round(_r * (_r / _c), 2)
    if ver < 10:       # v10: commission unit = £1,000 profit
        cfg["costs"]["unit_size"] = 1000.0
    if ver < 11:       # v11: as the telephony pricebook - £4,000 profit = 1 unit, £600 per unit (commission = 15% of profit)
        cfg["costs"]["unit_size"] = 4000.0; cfg["costs"]["unit_value"] = 600.0
    if ver < 12:       # v12: commission is still 15% of profit, but 1 unit = £1,000 commission, so the units shown match the commission paid
        cfg["costs"]["unit_size"] = 6666.67; cfg["costs"]["unit_value"] = 1000.0
    cfg["catalogue_version"] = 12
    if not cfg.get("terms"):
        cfg["terms"] = [list(t) for t in TERMS_DEFAULT]
    return cfg

if "cfg" not in st.session_state:
    st.session_state.cfg = load_config()
CFG = st.session_state.cfg
CO = CFG["company"]
CO.update(FIXED_CONTACT)
# SteadyTemp now trades as its own company (SteadyTemp LTD): replace the old SY Comms details if a saved config still has them
if "sy comms" in (str(CO.get("legal", "")) + str(CO.get("legal_line", ""))).lower() or "15722588" in str(CO.get("reg", "")):
    _d = default_config()["company"]
    CO.update(legal=_d["legal"], legal_line="", reg=_d["reg"], reg_office=_d["reg_office"])
CO.setdefault("reg_office", default_config()["company"]["reg_office"])
COST = CFG["costs"]
for _k, _v in default_config()["costs"].items():
    COST.setdefault(_k, _v)                     # any setting missing from a saved config takes its standard value

