def _rental_block(target=None):
    """Monthly rental (or cash price) with the payment profile, e.g. 1+83, in small type beside the label."""
    t = target or st
    none = CALC["n_all"] == 0
    if CALC["is_cash"]:
        lab, small, val, sub = "Cash price (ex VAT)", "", "-" if none else money(CALC["cash_price"]), "plus VAT"
    else:
        lab, small, val, sub = "Monthly rental", CALC["profile"], "-" if none else money(CALC["rental"]), "plus VAT · billed by the funder"
    t.markdown(f"<div style='display:flex;justify-content:space-between;align-items:baseline'><span style='font-size:.9rem;color:#9FB6CA'>{esc(lab)}</span>"
               f"<span style='font-size:.72rem;color:#7F95AA'>{esc(small)}</span></div>"
               f"<div style='font-size:1.9rem;font-weight:700;line-height:1.15'>{esc(val)}</div>"
               f"<div style='font-size:.75rem;color:#7F95AA;margin-bottom:.3rem'>{esc(sub)}</div>", unsafe_allow_html=True)
    if CALC.get("provisional") and not CALC["is_cash"]:
        t.caption("⚠️ The rates for this term are provisional - confirm with the office before quoting.")

